    bun: 1.3.14 - ..
  IDEs:
    VSCode: 1.128.0 - ..
  Languages:
    Bash: 5.1.16 - C:\WINDOWS\system32\bash.EXE
  npmPackages:
    @playwright/test: ^1.47.0 => 1.61.1
