// SPDX-License-Identifier: Apache-2.0
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const { webkit } = require('playwright');

(async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'pw-directory-race-'));
  const directory = path.join(root, 'authored');
  await fs.mkdir(path.join(directory, 'sub'), { recursive: true });
  await fs.writeFile(path.join(directory, 'alpha.txt'), 'alpha\n');
  await fs.writeFile(path.join(directory, 'sub', 'beta.txt'), 'beta\n');
  const expected = ['alpha\n', 'beta\n'];
  const browser = await webkit.launch();
  const version = browser.version();
  const context = await browser.newContext();
  let completed = 0;
  try {
    for (let iteration = 1; iteration <= 400; iteration++) {
      const page = await context.newPage();
      try {
        await page.setContent('<input id="files" type="file" webkitdirectory multiple>');
        await page.evaluate(() => {
          globalThis.events = { input: 0, change: 0, trusted: false };
          const input = document.querySelector('#files');
          input.addEventListener('input', event => { events.input++; events.trusted = event.isTrusted; });
          input.addEventListener('change', () => { events.change++; });
        });
        let uploadError;
        try {
