      }
    }
    process.stdout.write(JSON.stringify({ engine: 'webkit', version,
      sdk: require('playwright/package.json').version, freshPages: completed,
      uploadDeadlineMs: 30000, noFailedCallRetries: true }) + '\n');
  } finally {
    await context.close();
    await browser.close();
    await fs.rm(root, { recursive: true });
  }
})().catch(() => { process.stderr.write('native-directory-upload-failed\n'); process.exitCode = 1; });
